import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { UtilService } from 'src/app/services/util.service';
import { HttpClient } from '@angular/common/http';
import { CourseTypeService } from 'src/app/services/courses.service';
import { NavigationExtras } from '@angular/router';
import { register } from 'swiper/element';
import Swiper from 'swiper';

register();
@Component({
  selector: 'app-home',
  templateUrl: './home.page.html',
  styleUrls: ['./home.page.scss'],
})
export class HomePage implements OnInit {
  @ViewChild("swiper") swiper?: ElementRef<{ swiper: Swiper }>;

  slideOpts = {
    initialSlide: 0,
    slidesPerView: 1,
  };
  slideOptsCategories = {
    initialSlide: 1,
    slidesPerView: 3,
    spaceBetween: 10,
  };
  slideOptsCourseContent = {
    initialSlide: 0,
    slidesPerView: 3.2,
    spaceBetween: 10,
  };
  slideOptsCourse = {
    initialSlide: 0,
    slidesPerView: 1.5,
    spaceBetween: 10,
  };
  slideOptsMentors = {
    initialSlide: 0,
    slidesPerView: 4,
    spaceBetween: 10,
  };

  index: number = 0;
  activeCate: string = '';
  courseContent: string = '';
  coursesList: any[] = [];

  firstName: string = '';
  lastName: string = '';
  email: string = '';
  studentId: number = 0;
  faculty: string = '';
  department: string = '';
  validCompetencies: any[] = [];
  invalidCompetencies: any[] = [];
  validCompetenciesChunked: any[][] = [];

  studentPhoto: string = 'https://scontent.fosl5-1.fna.fbcdn.net/v/t39.30808-6/507043008_1897198064435258_4645908504950093973_n.jpg?_nc_cat=104&ccb=1-7&_nc_sid=6ee11a&_nc_ohc=hXdAxh3NOVkQ7kNvwEPJK_I&_nc_oc=Adlmmd6UYMThtRrKLbrJdYzGjVogj7WKzCJeWPgpqDhPtCDNaEkoXtZTFGecOujhlQNoCwwXpBNc4ckYEvL8q5pw&_nc_zt=23&_nc_ht=scontent.fosl5-1.fna&_nc_gid=kMMgdGP0r9jeIlLd1Cypkg&oh=00_AfPEUcUv_ARjEQsKTOnqzofozhDgy6YNGQIv9yX4jC_Zww&oe=68591725';
  qrCodeUrl: string = 'data:image/png;base64,'; // Replace or generate QR dynamically if needed

  constructor(
    public util: UtilService,
    private http: HttpClient,
    private courseTypeService: CourseTypeService
  ) {
    this.activeCate = this.util.categories[2];
    this.courseContent = this.util.categories[0];
    this.changeCourse();
  }

  ngOnInit() {
    this.fetchStudentData();
  }

  changeCourse() {
    const index = Math.floor(Math.random() * this.util.coursesList.length);
    this.coursesList = this.util.coursesList[index]?.list || [];
  }

  onSearch() {
    this.util.navigateToPage('/search');
  }

  slideChanged(event: any) {
    this.index = this.swiper?.nativeElement.swiper.activeIndex || 0;
  }

  changeActiveCate(name: string) {
    this.activeCate = name;
  }

  changeCourseContent(name: string) {
    this.courseContent = name;
    this.changeCourse();
  }

  onPage(name: string) {
    this.util.navigateToPage(name);
  }

  onCourseDetails(name: string, image: string, type: string) {
    const param: NavigationExtras = {
      queryParams: { name, image, type }
    };
    this.util.navigateToPage('course-details', param);
  }

  onMentorDetails(name: string, image: string) {
    const param: NavigationExtras = {
      queryParams: { name, image }
    };
    this.util.navigateToPage('mentor-details', param);
  }

  fetchStudentData() {
    const studentId = 1; // Replace with actual ID dynamically if needed
    this.courseTypeService.getStudentInfo(studentId).subscribe({
      next: (data: any) => {
        this.firstName = data.student.first_name;
        this.lastName = data.student.last_name;
        this.email = data.student.email;
        this.department = data.student.department;
        this.faculty = data.student.faculty;
        this.validCompetencies = data.competencies.valid;
        this.invalidCompetencies = data.competencies.invalid;

        this.validCompetenciesChunked = this.chunkArray(this.validCompetencies, 4);
      },
      error: (error: any) => {
        console.error('Error fetching student data:', error);
      }
    });
  }

  chunkArray(arr: any[], size: number): any[][] {
    const result = [];
    for (let i = 0; i < arr.length; i += size) {
      result.push(arr.slice(i, i + size));
    }
    return result;
  }
}